"""RESUMED INDEPENDENT DELTA REVIEW 05 probes (reference only; no host/runtime/signal claim)."""
import ast
import copy
import hashlib
import json
import sys
import types
from pathlib import Path
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012

S = Path(__file__).resolve().parent / 'subject'
pins = json.loads((S / 'input-pins.json').read_bytes())['inputs']
B = {}
for p in pins:
    b = (S / p['path']).read_bytes()
    assert len(b) == p['bytes'] and hashlib.sha256(b).hexdigest() == p['sha256'], p['path']
    B[p['path']] = b
manifest = json.loads((S.parent / 'manifest.json').read_bytes())
M = {f['path']: f['sha256'] for f in manifest['files']}


def verified(rel):
    data = (S / rel).read_bytes()
    assert hashlib.sha256(data).hexdigest() == M[rel], rel
    return data


ref = types.ModuleType('ref'); exec(compile(B['inputs/canonical.py'], 'canonical.py', 'exec'), ref.__dict__)
docs = {}
for path in sorted((S / 'inputs/schemas').glob('*.json')):
    d = ref.parse(verified(str(path.relative_to(S)))); docs[d['$id']] = d
V6 = ref.parse(verified('command-envelope.v6.schema.json')); docs[V6['$id']] = V6
REG = Registry().with_resources((k, Resource(contents={a: v for a, v in d.items() if a != '$schema'}, specification=DRAFT202012)) for k, d in docs.items())
INV_ID = 'urn:opensip:product-v1:workflows:evaluator3:invocation:3'
ENV_ID = V6['$id']
join = types.ModuleType('join'); exec(compile(verified('ledger_join.py'), 'ledger_join.py', 'exec'), join.__dict__)

succ = json.loads(verified('model-successor.json'))
text = B['inputs/workflows_model.v1.py'].decode()
assert hashlib.sha256(B['inputs/workflows_model.v1.py']).hexdigest() == succ['ownerSha256'] and text.count(succ['before']) == 1
WANT = {'Refusal', 'terminate', 'analysis_termination', 'comparison_termination', 'exit_code', 'validate_dag',
        'raw_sha', 'synthetic_execution_id', '_exec_id', 'run_invocation'}


def load(t):
    nodes = []
    for n in ast.parse(t).body:
        if isinstance(n, (ast.FunctionDef, ast.ClassDef)) and n.name in WANT:
            nodes.append(n)
        elif isinstance(n, ast.Assign):
            names = {x.id for x in n.targets if isinstance(x, ast.Name)}
            if names & WANT or (names and all(x.isupper() for x in names) and not any(isinstance(c, ast.Call) for c in ast.walk(n.value))):
                nodes.append(n)
    m = types.ModuleType('owner'); m.__dict__.update(hashlib=hashlib, json=json, canonical=ref)
    exec(compile(ast.Module(body=nodes, type_ignores=[]), 'workflows_model.v1.py#extract', 'exec'), m.__dict__)
    return m


PARENT, SUCC = load(text), load(text.replace(succ['before'], succ['after']))
fx = json.loads(B['inputs/report-fixtures04.json'])
gold = fx['deliveryGoldens'][24]['envelope']
ANALYSIS, RID, PID = gold['run'], gold['requestId'], gold['projectId']
SNAP = 'snapshot2:' + 'a' * 64
rows, fails = [], []


def shape(v, sid):
    try:
        ref.validate({'$ref': sid}, v, REG); return True
    except Exception as e:
        if type(e).__name__ not in ('ValidationError', 'AdmissionError'): raise
        return False


def J(rec, env):
    try:
        join.validate_interruption_join(rec, env); return 'accepted'
    except join.JoinRefusal as e:
        return str(e)
    except Exception as e:
        return 'UNTYPED:' + type(e).__name__


def row(name, got, want=None, **kw):
    r = {'case': name, 'got': got, **kw}
    if want is not None:
        r['want'] = want; r['ok'] = got == want
        if got != want: fails.append(name)
    else:
        r['observation'] = True
    rows.append(r)


# ---------- ledger builders (my own; repair values from pinned report fixtures)
RP = fx['bases']['repair-preview']['envelope']['queryRecord']


def params(i, kind, reqs, kinds):
    if kind == 'analysis':
        return {'kind': kind, 'profile': 'default', 'role': 'primary', 'durability': 'authoritative', 'snapshotSource': 'live-worktree'}
    if kind == 'render':
        return {'kind': kind, 'format': 'json', 'destination': 'stdout', 'sourceSteps': [j for j in range(i) if reqs[j] == 'required'], 'required': True}
    if kind == 'query':
        rq = copy.deepcopy(gold['advisoryReport']['request'])
        return {'kind': kind, 'operation': rq['operation'], 'completeness': rq['completeness'], 'page': rq['page'], 'request': rq}
    if kind == 'repair-preview':
        d = RP['plan']['descriptor']
        return {'kind': kind, 'evidenceSource': {'runId': d['evidenceRunId']}, 'recipe': copy.deepcopy(d['recipe']), 'targets': copy.deepcopy(d['targets'])}
    if kind == 'repair-apply':
        return {'kind': kind, 'planStep': kinds.index('repair-preview'), 'repairPlanId': RP['plan']['repairPlanId'],
                'consentSource': 'policy', 'authorizationRef': 'security.repair-apply-authorization.v1:' + 'b' * 64}
    if kind == 'verify':
        return {'kind': kind, 'afterStep': kinds.index('repair-apply'), 'profile': 'default'}
    raise ValueError(kind)


def verify_result(run_id='run3:' + 'd' * 64):
    r = copy.deepcopy(ANALYSIS); r.update(kind='verify', runId=run_id)
    r['verification'] = {'appliedSnapshotId': SNAP, 'verifiedSnapshotId': SNAP, 'snapshotMatched': True, 'targetsRemaining': 0, 'netNewFindings': 0}
    return r


def result_for(i, kind):
    if kind == 'analysis':
        r = copy.deepcopy(ANALYSIS); r['runId'] = 'run3:' + format(i + 1, 'x') * 64; return r
    if kind == 'render':
        return {'kind': 'render', 'format': 'json', 'rendererVersion': 1, 'bytes': 7, 'truncation': False, 'written': True}
    if kind == 'query':
        return {'kind': 'query', 'items': 1, 'truncated': False, 'completenessMet': True, 'advisory': True}
    if kind == 'repair-preview':
        r = copy.deepcopy(RP['preview']); r['applicable'] = True; return r
    if kind == 'repair-apply':
        return {'kind': 'repair-apply', 'receiptId': 'receipt2:' + 'b' * 64, 'effectOutcome': 'COMPLETED', 'journalState': 'COMMITTED',
                'rollback': 'not-needed', 'appliedSnapshotId': SNAP}
    if kind == 'verify':
        return verify_result()


def base(kinds, reqs):
    steps = [{'stepId': i, 'kind': k, 'requirement': reqs[i], 'dependsOn': [j for j in range(i) if reqs[j] == 'required' or reqs[i] == 'optional'],
              'dependencyGate': 'terminal' if k == 'render' else 'completed', 'retryPolicy': 'none', 'params': params(i, k, reqs, kinds)} for i, k in enumerate(kinds)]
    builtin = {('analysis', 'render'): 'default', ('repair-preview', 'repair-apply', 'verify', 'render'): 'repair-apply'}.get(tuple(kinds))
    wf = {'kind': 'builtin', 'name': builtin} if builtin and 'optional' not in reqs else \
        {'kind': 'profile', 'contributionId': 'org.example.workflow', 'activationId': 'review', 'profileVersion': '1.0.0'}
    return {'schemaFamily': 'opensip.product.invocation', 'schemaMajor': 3, 'requestId': RID, 'projectId': PID,
            'workflow': wf, 'mode': {'interactive': False, 'ci': True, 'ephemeral': False}, 'orderedSteps': steps}


def gen(model, kinds, reqs=None, cut=None, sig='SIGINT', over=None):
    reqs = reqs or ['required'] * len(kinds)
    sc = {str(i): [{'event': 'completed', 'result': result_for(i, k)}] for i, k in enumerate(kinds)}
    sc.update(over or {})
    if cut is not None:
        sc['cancelAt'] = {'stepId': cut, 'signal': sig}
    return model.run_invocation(base(kinds, reqs), sc)


def details(rec):
    return [r['termination']['domainDetail'] for r in rec['stepResults']
            if r['outcome'] not in ('cancelled', 'skipped') and r['termination']['class'] in ('request-rejected', 'operational-failed')
            and 'domainDetail' in r['termination']]


def carrier(rec, kind=None):
    """Reviewer's reading of the selected deterministic rule."""
    t = rec['termination']
    kind = kind or ('run' if t.get('runId') else 'failure')
    e = {'schemaFamily': 'opensip.product.envelope', 'schemaMajor': 6, 'kind': kind, 'requestId': rec['requestId'],
         'projectId': rec['projectId'], 'termination': copy.deepcopy(t), 'exitCode': 130 if t['class'] == 'interrupted' else PARENT.exit_code(t)}
    if kind == 'run':
        e['run'] = copy.deepcopy(next(r['result'] for r in reversed(rec['stepResults']) if r.get('result', {}).get('runId') == t.get('runId')))
    elif kind == 'invocation':
        e['invocation'] = copy.deepcopy(rec)
    ds = details(rec)
    if t['class'] == 'interrupted' and (ds or kind == 'failure'):
        e['errors'] = copy.deepcopy(ds)
    elif kind == 'failure':
        e['errors'] = [{'code': 'CONFIG.INVALID', 'remedy': 'settled placeholder'}]
    return e


# ================= V1 exact result kinds
REPAIR = ['repair-preview', 'repair-apply', 'verify', 'render']
per_kind = {}
inv_defs = docs[INV_ID]['$defs']
te = docs['urn:opensip:product-v1:workflows:test-execution']['$defs']['TestExecutionStepResult']
per_kind['test-execution'] = te.get('properties', {}).get('kind')
row('V1a-test-execution-result-kind-const', per_kind['test-execution'], {'const': 'test-execution'},
    note='the only StepDomainResult reached through $ref; exact spec.kind equality is safe only if its kind const equals the step kind')
for reqs, label in [(['required'] * 4, 'required-verify'), (['required', 'required', 'optional', 'required'], 'optional-verify')]:
    for cut in [None, 2, 3, 4]:
        rec, code = gen(SUCC, REPAIR, reqs, cut)
        envs = [carrier(rec)] + ([carrier(rec, 'invocation')] if rec['termination']['class'] == 'interrupted' else [])
        got = {'recordShape': shape(rec, INV_ID), 'term': rec['termination'], 'exit': code,
               'carriers': [(e['kind'], shape(e, ENV_ID), J(rec, e)) for e in envs]}
        ok = got['recordShape'] and all(s and j == 'accepted' for _, s, j in got['carriers'])
        row('V1b-%s-cut-%s' % (label, cut), ok, True, detail=got)
# wrong kinds in both directions, both shapes valid
rec, _ = gen(SUCC, REPAIR, None, 3)
w1 = copy.deepcopy(rec); r = w1['stepResults'][2]['result']; r['kind'] = 'analysis'; r.pop('verification')
row('V1c-verify-step-with-analysis-kind', (shape(w1, INV_ID), J(w1, carrier(w1))), (True, 'J-INTERRUPTION-RESULT-KIND'))
rec_a, _ = gen(SUCC, ['analysis', 'render'], None, 1)
w2 = copy.deepcopy(rec_a); w2['stepResults'][0]['result'] = verify_result(w2['stepResults'][0]['result']['runId'])
row('V1d-analysis-step-with-verify-kind', (shape(w2, INV_ID), J(w2, carrier(w2))), (True, 'J-INTERRUPTION-RESULT-KIND'))
row('V1e-apply-step-with-preview-result', J(*(lambda x: (x, carrier(x)))(
    (lambda y: (y['stepResults'][1].__setitem__('result', result_for(0, 'repair-preview')), y)[1])(copy.deepcopy(rec)))), 'J-INTERRUPTION-RESULT-KIND')

# ================= model successor differential (my own repair ledgers)
changed = 0
for reqs in (['required'] * 4, ['required', 'required', 'optional', 'required']):
    for cut in [None, 0, 1, 2, 3, 4]:
        for sig in ('SIGINT', 'SIGTERM', 'SIGHUP'):
            if cut is None and sig != 'SIGINT': continue
            a, ca = gen(PARENT, REPAIR, reqs, cut, sig)
            b, cb = gen(SUCC, REPAIR, reqs, cut, sig)
            assert a['stepResults'] == b['stepResults'] and ca == cb
            if a['termination'] != b['termination']:
                changed += 1
                assert reqs[2] == 'optional' and b['termination'].get('runId') == 'run3:' + 'd' * 64
row('M1-repair-parent-vs-successor-changed-cases', changed, 3, note='optional verify: cut 3 x 3 signals; step results and exits identical')
sv, cs = gen(SUCC, REPAIR, ['required', 'required', 'optional', 'required'], None)
si, ci = gen(SUCC, REPAIR, ['required', 'required', 'optional', 'required'], 3)
row('M2-optional-verify-asymmetry', ({'settled': sv['termination'], 'exit': cs}, {'interrupted': si['termination'], 'exit': ci}),
    ({'settled': {'class': 'success'}, 'exit': 0}, {'interrupted': {'class': 'interrupted', 'signal': 'SIGINT', 'runId': 'run3:' + 'd' * 64}, 'exit': 130}))

# ================= V2 deterministic errors
CFG = {'code': 'CONFIG.INVALID', 'remedy': 'Correct the invalid configuration.'}
k3, r3 = ['analysis', 'analysis', 'render'], ['optional', 'required', 'required']
b3 = base(k3, r3); b3['orderedSteps'][1]['dependsOn'] = []; b3['orderedSteps'][2]['dependsOn'] = [1]; b3['orderedSteps'][2]['params']['sourceSteps'] = [1]
rej = [{'event': 'rejected', 'errorCode': 'CONFIG.INVALID', 'detail': 'CONFIG.INVALID', 'remedy': CFG['remedy']}]


def run3(cut, over):
    sc = {'0': [{'event': 'completed', 'result': result_for(0, 'analysis')}], '1': [{'event': 'completed', 'result': result_for(1, 'analysis')}],
          '2': [{'event': 'completed', 'result': result_for(2, 'render')}], 'cancelAt': {'stepId': cut, 'signal': 'SIGINT'}}
    sc.update(over)
    return SUCC.run_invocation(copy.deepcopy(b3), sc)[0]


no_run_err = run3(1, {'0': rej})           # optional rejected with detail, required analysis cancelled
run_err = run3(2, {'0': rej})              # optional rejected, required analysis committed, render cancelled
no_run_clean = run3(1, {})                 # optional analysis committed Run! -> run carrier, empty list
pure_clean, _ = gen(SUCC, ['analysis', 'render'], None, 0)   # no Run, no details
row('V2-fixture-shapes', [shape(x, INV_ID) for x in (no_run_err, run_err, no_run_clean, pure_clean)], [True] * 4)


def variant(rec, kind, errors):
    e = carrier(rec, kind)
    if errors == 'ABSENT':
        e.pop('errors', None)
    else:
        e['errors'] = errors
    return e


for label, rec, kind, errors, want in [
    ('failure-nonempty-exact', no_run_err, 'failure', [CFG], (True, 'accepted')),
    ('failure-nonempty-as-empty', no_run_err, 'failure', [], (True, 'J-INTERRUPTION-INVENTED-DETAIL')),
    ('invocation-nonempty-exact', no_run_err, 'invocation', [CFG], (True, 'accepted')),
    ('invocation-nonempty-omitted', no_run_err, 'invocation', 'ABSENT', (True, 'J-INTERRUPTION-INVENTED-DETAIL')),
    ('run-nonempty-exact', run_err, 'run', [CFG], (True, 'accepted')),
    ('run-nonempty-omitted', run_err, 'run', 'ABSENT', (True, 'J-INTERRUPTION-INVENTED-DETAIL')),
    ('run-nonempty-duplicated', run_err, 'run', [CFG, CFG], (True, 'J-INTERRUPTION-INVENTED-DETAIL')),
    ('run-nonempty-remedy-changed', run_err, 'run', [{**CFG, 'remedy': 'other'}], (True, 'J-INTERRUPTION-INVENTED-DETAIL')),
    ('failure-empty-list', pure_clean, 'failure', [], (True, 'accepted')),
